-- East Africa Online: marketplace taxonomy foundation
-- Additive only. Existing product rows and existing RLS policies are preserved.
-- Taxonomy seed: 0.1.0; generated from docs/marketplace-taxonomy/taxonomy.v1.json.

create table if not exists public.marketplace_taxonomy_nodes (
  id text primary key,
  parent_id text references public.marketplace_taxonomy_nodes(id) on update cascade on delete restrict,
  code text not null,
  label text not null,
  node_kind text not null check (node_kind in ('main_category','subcategory','product_type')),
  sort_order integer not null default 0,
  is_active boolean not null default true,
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique(parent_id, code)
);

create index if not exists marketplace_taxonomy_nodes_parent_idx
  on public.marketplace_taxonomy_nodes(parent_id, sort_order);
create index if not exists marketplace_taxonomy_nodes_kind_idx
  on public.marketplace_taxonomy_nodes(node_kind, is_active);

create table if not exists public.marketplace_attribute_definitions (
  code text primary key,
  label text not null,
  data_type text not null,
  tier text not null check (tier in ('essential','recommended','advanced','regulatory')),
  config jsonb not null default '{}'::jsonb,
  is_active boolean not null default true,
  created_at timestamptz not null default now()
);

create table if not exists public.marketplace_attribute_profiles (
  code text primary key,
  essential_attributes text[] not null default '{}',
  recommended_attributes text[] not null default '{}',
  advanced_attributes text[] not null default '{}',
  created_at timestamptz not null default now()
);

create table if not exists public.marketplace_taxonomy_node_profiles (
  node_id text not null references public.marketplace_taxonomy_nodes(id) on update cascade on delete cascade,
  profile_code text not null references public.marketplace_attribute_profiles(code) on update cascade on delete restrict,
  primary key(node_id, profile_code)
);

create table if not exists public.marketplace_taxonomy_aliases (
  id bigint generated by default as identity primary key,
  term text not null,
  normalized_term text generated always as (lower(trim(term))) stored,
  language text not null default 'en',
  node_id text not null references public.marketplace_taxonomy_nodes(id) on update cascade on delete cascade,
  created_at timestamptz not null default now(),
  unique(normalized_term, language, node_id)
);
create index if not exists marketplace_taxonomy_aliases_lookup_idx
  on public.marketplace_taxonomy_aliases(normalized_term, language);

create table if not exists public.marketplace_listing_kinds (
  code text primary key,
  label text not null,
  is_active boolean not null default true
);

create table if not exists public.marketplace_listing_kind_profiles (
  listing_kind text not null references public.marketplace_listing_kinds(code) on update cascade on delete cascade,
  profile_code text not null references public.marketplace_attribute_profiles(code) on update cascade on delete restrict,
  primary key(listing_kind, profile_code)
);

-- Link existing product records to the new taxonomy without forcing a backfill.
alter table public.products
  add column if not exists listing_kind text not null default 'physical_product',
  add column if not exists taxonomy_node_id text references public.marketplace_taxonomy_nodes(id) on update cascade on delete restrict,
  add column if not exists classification_status text not null default 'unclassified';

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'products_listing_kind_check') then
    alter table public.products add constraint products_listing_kind_check
      check (listing_kind in ('physical_product','service','digital_product','rental','rfq'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'products_classification_status_check') then
    alter table public.products add constraint products_classification_status_check
      check (classification_status in ('unclassified','suggested','confirmed','needs_correction','manual_review','approved'));
  end if;
end $$;

create index if not exists products_taxonomy_node_idx on public.products(taxonomy_node_id);
create index if not exists products_listing_kind_idx on public.products(listing_kind, classification_status);

insert into public.marketplace_listing_kinds(code,label) values
 ('physical_product','Physical product'),('service','Service'),('digital_product','Digital product'),
 ('rental','Rental / hire'),('rfq','Request for quotation')
on conflict (code) do update set label=excluded.label;

