insert into public.marketplace_taxonomy_aliases(term,language,node_id)
select x.term,x.language,x.maps_to
from jsonb_to_recordset('"[{\"term\":\"mahindi\",\"language\":\"sw\",\"maps_to\":\"agriculture-livestock.crops-produce.maize-grain\"},{\"term\":\"corn\",\"language\":\"en\",\"maps_to\":\"agriculture-livestock.crops-produce.maize-grain\"},{\"term\":\"maharagwe\",\"language\":\"sw\",\"maps_to\":\"agriculture-livestock.crops-produce.beans-pulses\"},{\"term\":\"panga\",\"language\":\"sw\",\"maps_to\":\"agriculture-livestock.farm-tools.panga-machete\"},{\"term\":\"jembe\",\"language\":\"sw\",\"maps_to\":\"agriculture-livestock.farm-tools.hand-hoe-jembe\"},{\"term\":\"boda boda\",\"language\":\"regional\",\"maps_to\":\"automotive-transport.two-three-wheelers.motorcycle\"},{\"term\":\"matatu\",\"language\":\"sw\",\"maps_to\":\"automotive-transport.commercial-vehicles.minibus-matatu\"},{\"term\":\"posho mill\",\"language\":\"en-ke\",\"maps_to\":\"agriculture-livestock.farm-machinery.posho-mill\"}]"'::jsonb) as x(term text,language text,maps_to text)
on conflict (normalized_term,language,node_id) do nothing;

-- Public clients may read active catalogue metadata; writes are reserved for trusted server/admin workflows.
alter table public.marketplace_taxonomy_nodes enable row level security;
alter table public.marketplace_attribute_definitions enable row level security;
alter table public.marketplace_attribute_profiles enable row level security;
alter table public.marketplace_taxonomy_node_profiles enable row level security;
alter table public.marketplace_taxonomy_aliases enable row level security;
alter table public.marketplace_listing_kinds enable row level security;
alter table public.marketplace_listing_kind_profiles enable row level security;

drop policy if exists "Public can read active taxonomy nodes" on public.marketplace_taxonomy_nodes;
create policy "Public can read active taxonomy nodes" on public.marketplace_taxonomy_nodes
 for select to anon, authenticated using (is_active = true);
drop policy if exists "Public can read active attribute definitions" on public.marketplace_attribute_definitions;
create policy "Public can read active attribute definitions" on public.marketplace_attribute_definitions
 for select to anon, authenticated using (is_active = true);
drop policy if exists "Public can read attribute profiles" on public.marketplace_attribute_profiles;
create policy "Public can read attribute profiles" on public.marketplace_attribute_profiles
 for select to anon, authenticated using (true);
drop policy if exists "Public can read taxonomy node profiles" on public.marketplace_taxonomy_node_profiles;
create policy "Public can read taxonomy node profiles" on public.marketplace_taxonomy_node_profiles
 for select to anon, authenticated using (true);
drop policy if exists "Public can read taxonomy aliases" on public.marketplace_taxonomy_aliases;
create policy "Public can read taxonomy aliases" on public.marketplace_taxonomy_aliases
 for select to anon, authenticated using (true);
drop policy if exists "Public can read listing kinds" on public.marketplace_listing_kinds;
create policy "Public can read listing kinds" on public.marketplace_listing_kinds
 for select to anon, authenticated using (is_active = true);
drop policy if exists "Public can read listing kind profiles" on public.marketplace_listing_kind_profiles;
create policy "Public can read listing kind profiles" on public.marketplace_listing_kind_profiles
 for select to anon, authenticated using (true);

comment on table public.marketplace_taxonomy_nodes is 'Versioned East Africa-first category hierarchy; product types are leaf nodes.';
comment on column public.products.taxonomy_node_id is 'Primary marketplace product/service type; null for legacy or unclassified listings.';
comment on column public.products.classification_status is 'Classification workflow state; does not replace product_status.';
